// Draws the homelab network topology from /data/homelab.json.
// That file is generated by homelab-infra (scripts/gen-public.py); don't edit it here.
//
// Zones, machines and services are HTML. The wires (internet -> router ->
// backbone -> each zone) are an SVG layer behind them, measured from the
// laid-out cards and redrawn whenever the layout changes.
(function () {
  var net = document.getElementById("net");
  var map = document.getElementById("lab-map");
  var svg = document.getElementById("net-wires");
  var detail = document.getElementById("net-detail");
  if (!net || !map || !svg) return;

  var SVGNS = "http://www.w3.org/2000/svg";
  var GROUPS = [
    { id: "infrastructure", label: "Infrastructure" },
    { id: "people", label: "People" },
    { id: "household", label: "Household" },
    { id: "contained", label: "Contained" }
  ];
  var ICONS = {
    cloud: '<path d="M7 18h10.5a4 4 0 0 0 .4-7.98A6 6 0 0 0 6.2 9.4 4.3 4.3 0 0 0 7 18z"/>',
    router: '<rect x="3" y="12" width="18" height="7" rx="2"/><path d="M7 12V5M17 12V5"/><circle cx="7.5" cy="15.5" r=".6"/><circle cx="10.5" cy="15.5" r=".6"/>',
    network: '<rect x="2" y="8" width="20" height="8" rx="2"/><path d="M6 12h1.5M9.5 12H11M13 12h1.5M16.5 12H18"/>',
    compute: '<rect x="4" y="3" width="16" height="7" rx="1.5"/><rect x="4" y="14" width="16" height="7" rx="1.5"/><path d="M8 6.5h.01M8 17.5h.01"/>',
    pi: '<rect x="6" y="6" width="12" height="12" rx="2"/><path d="M9 3v3M15 3v3M9 18v3M15 18v3M3 9h3M3 15h3M18 9h3M18 15h3"/>',
    storage: '<ellipse cx="12" cy="6" rx="7" ry="2.5"/><path d="M5 6v12c0 1.4 3.1 2.5 7 2.5s7-1.1 7-2.5V6M5 12c0 1.4 3.1 2.5 7 2.5s7-1.1 7-2.5"/>',
    workstation: '<rect x="3" y="4" width="18" height="12" rx="1.5"/><path d="M9 20h6M12 16v4"/>',
    vm: '<path d="M4 8l8-4 8 4v8l-8 4-8-4zM4 8l8 4 8-4M12 12v8"/>',
    wireless: '<path d="M5 10.5a10 10 0 0 1 14 0M8 13.5a6 6 0 0 1 8 0"/><circle cx="12" cy="17" r="1"/>',
    power: '<rect x="4" y="7" width="14" height="10" rx="2"/><path d="M20 10.5v3M11.5 9l-2 3.5h3l-2 3.5"/>',
    house: '<path d="M4 11l8-7 8 7v9H4z"/><path d="M10 20v-5h4v5"/>',
    phone: '<rect x="7" y="3" width="10" height="18" rx="2"/><path d="M11 18h2"/>'
  };
  // Things on these networks that the repo doesn't track one by one.
  var EXTRA = {
    TRUSTED: { icon: "phone", name: "Phones & laptops", meta: "Personal devices" },
    GUEST: { icon: "phone", name: "Visitors' devices", meta: "Internet, DNS, and the printer" },
    PRACTICE: { icon: "vm", name: "Exercise VMs", meta: "Built for one exercise, then torn down" }
  };

  var data, zonesById = {}, hostsById = {}, selected = null;

  function esc(s) {
    return String(s == null ? "" : s).replace(/[&<>"]/g, function (c) {
      return { "&": "&amp;", "<": "&lt;", ">": "&gt;", '"': "&quot;" }[c];
    });
  }
  function icon(name) {
    return '<span class="net-icon"><svg viewBox="0 0 24 24" aria-hidden="true">' + ICONS[name] + "</svg></span>";
  }
  function shortName(label) { return label.replace(/^HP /, ""); }

  // ---- markup -------------------------------------------------------------

  function chip(s) {
    var name = s.repo
      ? '<a href="' + esc(s.repo) + '" target="_blank" rel="noopener">' + esc(s.label) + "</a>"
      : esc(s.label);
    return '<li class="chip' + (s.repo ? " chip-link" : "") + '"' +
      (s.purpose ? ' title="' + esc(s.purpose) + '"' : "") + ">" + name + "</li>";
  }

  function hostBlock(opts) {
    return '<div class="nh' + (opts.cls ? " " + opts.cls : "") + '"' +
      (opts.host ? ' data-host="' + esc(opts.host) + '" tabindex="0"' : "") + ">" +
      icon(opts.icon) +
      '<div class="nh-text"><p class="nh-name">' + esc(opts.name) +
      "</p>" +
      (opts.meta ? '<p class="nh-meta">' + esc(opts.meta) + "</p>" : "") + "</div>" +
      (opts.chips && opts.chips.length ? '<ul class="chips">' + opts.chips.map(chip).join("") + "</ul>" : "") +
      "</div>";
  }

  function zoneCard(z) {
    var here = data.hosts.filter(function (h) { return h.zone === z.id; });
    var svcs = data.services.filter(function (s) { return s.zone === z.id; });
    var order = here.map(function (h) { return h.id; });
    svcs.forEach(function (s) {
      var key = s.host || "_none";
      if (order.indexOf(key) < 0) order.push(key);
    });

    var body = order.map(function (id) {
      var h = hostsById[id];
      var list = svcs.filter(function (s) { return (s.host || "_none") === id; });
      if (!h) return hostBlock({ icon: "vm", name: "Shared", cls: "nh-remote", chips: list });
      if (h.zone !== z.id) {
        return hostBlock({ icon: "vm", host: h.id, name: shortName(h.label),
          meta: "VMs & containers · node sits in " + zonesById[h.zone].label,
          cls: "nh-remote", chips: list });
      }
      return hostBlock({ icon: h.group, host: h.id, name: shortName(h.label),
        meta: [h.role, h.ram].filter(Boolean).join(" · "), chips: list });
    }).join("");

    if (data.household[z.id]) {
      body += hostBlock({ icon: "house", name: data.household[z.id] + " household devices",
        meta: "TVs, appliances, sensors, printers", cls: "nh-extra" });
    }
    if (EXTRA[z.id]) body += hostBlock({ icon: EXTRA[z.id].icon, name: EXTRA[z.id].name, meta: EXTRA[z.id].meta, cls: "nh-extra" });

    return '<article class="nz nz-' + z.group + (z.id === "SERVERS" ? " nz-wide" : "") + '" data-zone="' + z.id + '">' +
      '<button type="button" class="nz-head" aria-pressed="false">' +
      '<span class="nz-vlan">' + esc(z.vlan) + "</span>" +
      '<span class="nz-name">' + esc(z.label) + "</span>" +
      "</button>" +
      '<p class="nz-rule"></p>' +
      '<div class="nz-body">' + body + "</div></article>";
  }

  // Small zones that share one column, one card under the other.
  var STACKS = [["DEV", "TALOS"]];
  function layout(zones) {
    var done = {}, out = "";
    zones.forEach(function (z) {
      if (done[z.id]) return;
      var stack = STACKS.filter(function (st) { return st.indexOf(z.id) >= 0; })[0];
      if (!stack) { out += zoneCard(z); return; }
      out += '<div class="nz-stack">' + stack.map(function (id) {
        done[id] = true;
        return zonesById[id] ? zoneCard(zonesById[id]) : "";
      }).join("") + "</div>";
    });
    return out;
  }

  function render() {
    map.innerHTML = GROUPS.map(function (g) {
      var zones = data.zones.filter(function (z) { return z.group === g.id; });
      return '<div class="net-group net-group-' + g.id + '"><p class="net-group-label">' + esc(g.label) + "</p>" +
        '<div class="net-zones">' + layout(zones) + "</div></div>";
    }).join("");
    showDetail(null);
    wire();
    draw();
  }

  // ---- detail panel -------------------------------------------------------

  function showDetail(z) {
    if (!detail) return;
    if (!z) {
      detail.innerHTML = '<p class="nd-hint">Pick a zone to trace its traffic through the router.</p>';
      return;
    }
    var reach = z.reach.map(function (r) {
      return "<li><strong>" + esc(zonesById[r.to].label) + "</strong>" + (r.how === "all" ? "" : " · " + esc(r.how)) + "</li>";
    });
    reach.push("<li><strong>Internet</strong>" + (z.internet === "yes" ? "" : " · " + esc(z.internet)) + "</li>");
    detail.style.setProperty("--zc", "var(--" + z.group + ")");
    detail.innerHTML = '<div class="nd-zone"><span class="nz-vlan">' + esc(z.vlan) + "</span>" +
      "<div><p class=\"nd-name\">" + esc(z.label) + "</p><p class=\"nd-purpose\">" + esc(z.purpose) + "</p></div></div>" +
      '<div class="nd-reach"><p>Can start connections to</p><ul>' + reach.join("") + "</ul></div>";
  }

  // ---- interaction --------------------------------------------------------

  function select(id) {
    selected = selected === id ? null : id;
    var z = selected && zonesById[selected];
    var targets = {};
    if (z) z.reach.forEach(function (r) { targets[r.to] = r.how; });
    Array.prototype.forEach.call(map.querySelectorAll(".nz"), function (card) {
      var zid = card.getAttribute("data-zone");
      card.classList.toggle("is-source", zid === selected);
      card.classList.toggle("is-target", zid in targets);
      card.querySelector(".nz-head").setAttribute("aria-pressed", String(zid === selected));
      card.querySelector(".nz-rule").textContent =
        zid in targets ? (targets[zid] === "all" ? "Allowed" : targets[zid]) : "";
    });
    net.classList.toggle("has-selection", !!z);
    showDetail(z);
    draw();
  }

  function lightHost(id) {
    net.classList.toggle("has-host", !!id);
    Array.prototype.forEach.call(map.querySelectorAll(".nh[data-host]"), function (el) {
      el.classList.toggle("is-lit", el.getAttribute("data-host") === id);
    });
  }

  function wire() {
    Array.prototype.forEach.call(map.querySelectorAll(".nz"), function (card) {
      card.querySelector(".nz-head").addEventListener("click", function () {
        select(card.getAttribute("data-zone"));
      });
    });
    Array.prototype.forEach.call(map.querySelectorAll(".nh[data-host]"), function (el) {
      var id = el.getAttribute("data-host");
      el.addEventListener("mouseenter", function () { lightHost(id); });
      el.addEventListener("mouseleave", function () { lightHost(null); });
      el.addEventListener("focus", function () { lightHost(id); });
      el.addEventListener("blur", function () { lightHost(null); });
    });
  }

  // ---- wires --------------------------------------------------------------

  function box(el) {
    var a = el.getBoundingClientRect(), b = net.getBoundingClientRect();
    return { x: a.left - b.left, y: a.top - b.top, w: a.width, h: a.height,
             cx: a.left - b.left + a.width / 2, bottom: a.bottom - b.top };
  }
  function path(d, cls) {
    var p = document.createElementNS(SVGNS, "path");
    p.setAttribute("d", d);
    p.setAttribute("class", cls);
    svg.appendChild(p);
    return p;
  }
  function dot(x, y, cls) {
    var c = document.createElementNS(SVGNS, "circle");
    c.setAttribute("cx", x); c.setAttribute("cy", y); c.setAttribute("r", 3.5);
    c.setAttribute("class", cls);
    svg.appendChild(c);
  }

  function draw() {
    while (svg.firstChild) svg.removeChild(svg.firstChild);
    var cards = Array.prototype.filter.call(map.querySelectorAll(".nz"), function (c) { return c.offsetParent; });
    if (!data || !cards.length || window.innerWidth < 760) return;

    svg.setAttribute("width", net.scrollWidth);
    svg.setAttribute("height", net.scrollHeight);
    svg.setAttribute("viewBox", "0 0 " + net.scrollWidth + " " + net.scrollHeight);

    var inet = box(document.getElementById("net-internet"));
    var router = box(document.getElementById("net-router"));
    var rx = router.cx, rb = router.bottom;

    // Rows of cards, top to bottom; each row hangs off its own bus.
    var rows = [];
    cards.forEach(function (c) {
      var b = box(c);
      // A stacked card hangs off the same bus as the card above it; its wire
      // runs behind that card.
      var anchor = c.parentElement.classList.contains("nz-stack") ? box(c.parentElement) : b;
      var row = rows.filter(function (r) { return Math.abs(r.top - anchor.y) < 8; })[0];
      if (!row) { row = { top: anchor.y, cards: [] }; rows.push(row); }
      row.top = Math.min(row.top, anchor.y);
      row.cards.push({ el: c, b: b, zone: c.getAttribute("data-zone") });
    });
    rows.sort(function (a, b) { return a.top - b.top; });
    var spine = Math.min.apply(null, cards.map(function (c) { return box(c).x; })) - 14;
    var paths = {};

    rows.forEach(function (row, i) {
      row.bus = row.top - 14;
      var xs = row.cards.map(function (c) { return c.b.cx; });
      var left = i === 0 ? Math.min(spine, Math.min.apply(null, xs)) : spine;
      var right = Math.max.apply(null, xs.concat(i === 0 ? [rx] : []));
      path("M" + left + " " + row.bus + "H" + right, "wire wire-bus");
      row.cards.forEach(function (c) {
        path("M" + c.b.cx + " " + row.bus + "V" + c.b.y, "wire wire-drop");
        dot(c.b.cx, c.b.y, "port port-" + c.el.className.match(/nz-(\w+)/)[1]);
        paths[c.zone] = "M" + rx + " " + rb + "V" + rows[0].bus +
          (i === 0 ? "" : "H" + spine + "V" + row.bus) + "H" + c.b.cx + "V" + c.b.y;
      });
    });
    path("M" + inet.cx + " " + inet.bottom + "V" + router.y, "wire wire-uplink");
    path("M" + rx + " " + rb + "V" + rows[0].bus, "wire wire-trunk");
    if (rows.length > 1) path("M" + spine + " " + rows[0].bus + "V" + rows[rows.length - 1].bus, "wire wire-spine");
    dot(rx, rb, "port port-core");

    // Selected zone: traffic climbs to the router, then down to each zone it may reach.
    var z = selected && zonesById[selected];
    if (z && paths[z.id]) {
      path(paths[z.id], "flow flow-up");
      z.reach.forEach(function (r) { if (paths[r.to]) path(paths[r.to], "flow flow-down"); });
      if (z.internet === "yes") path("M" + rx + " " + router.y + "V" + inet.bottom, "flow flow-out");
    }
  }

  var queued = false;
  function redraw() {
    if (queued) return;
    queued = true;
    requestAnimationFrame(function () { queued = false; draw(); });
  }
  if (window.ResizeObserver) new ResizeObserver(redraw).observe(map);
  window.addEventListener("resize", redraw);

  Array.prototype.forEach.call(net.querySelectorAll(".net-icon[data-icon]"), function (el) {
    el.outerHTML = icon(el.getAttribute("data-icon"));
  });

  fetch("/data/homelab.json", { cache: "no-cache" })
    .then(function (r) { if (!r.ok) throw new Error(r.status); return r.json(); })
    .then(function (d) {
      data = d;
      d.zones.forEach(function (z) { zonesById[z.id] = z; });
      d.hosts.forEach(function (h) { hostsById[h.id] = h; });
      render();
      var m = /zone=([A-Z]+)/.exec(location.hash);
      if (m && zonesById[m[1]]) select(m[1]);
      if (document.fonts && document.fonts.ready) document.fonts.ready.then(redraw);
    })
    .catch(function () {
      map.innerHTML = '<p class="nz-empty">The topology data didn\'t load. Try refreshing the page.</p>';
    });
})();
